#include <iostream>
#include <vector>
#include <algorithm>
#include <cstddef>

int main() {
    std::vector<int> original{6, -2, 6, 9, -2, 6};
    auto ordenados = original;
    std::sort(ordenados.begin(), ordenados.end());
    std::size_t inicio = 0;
    std::size_t distintos = 0;
    std::size_t suma = 0;
    std::cout << "Frequencies:\n";
    while (inicio < ordenados.size()) {
        std::size_t fin = inicio + 1;
        while (fin < ordenados.size() && ordenados[fin] == ordenados[inicio]) {
            ++fin;
        }
        std::size_t frecuencia = fin - inicio;
        std::cout << "[" << ordenados[inicio] << "]=" << frecuencia << "\n";
        ++distintos;
        suma += frecuencia;
        inicio = fin;
    }
    std::cout << "N:" << original.size() << "\nDistinct:" << distintos
              << "\nSum:" << suma << "\nOriginal:";
    for (int valor : original) { std::cout << valor << ";"; }
    std::cout << "\n";
    return 0;
}

